import { readdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';

const bundleDirectory = join(
  import.meta.dir,
  '../.skillset/plugins/trails-dev/skills/trails-adrs/scripts/lib'
);
const build = await Bun.build({
  banner:
    '// Generated by bun run adr:parser:build. See markdown-parser.LICENSE.txt.',
  entrypoints: [join(import.meta.dir, 'adr-markdown-parser.ts')],
  metafile: true,
  minify: true,
  target: 'bun',
});
const [bundle] = build.outputs;
if (
  !build.success ||
  !build.metafile ||
  build.outputs.length !== 1 ||
  !bundle ||
  Object.values(build.metafile.outputs).some(({ imports }) => imports.length)
) {
  throw new Error('Expected one self-contained ADR Markdown parser bundle');
}

const packageDirectories = new Set<string>();
for (const input of Object.keys(build.metafile.inputs)) {
  if (input.includes('node_modules/')) {
    packageDirectories.add(
      /^(.*node_modules\/(?:@[^/]+\/)?[^/]+)\//.exec(input)?.[1] ??
        dirname(input)
    );
  }
}

const notices: string[] = [];
for (const directory of packageDirectories) {
  const manifest = await Bun.file(join(directory, 'package.json')).json();
  const files = await readdir(directory);
  const filename = files.find((name) => /^license(?:\.txt|\.md)?$/i.test(name));
  if (!filename) {
    throw new Error(
      `No license found for ${manifest.name}@${manifest.version}`
    );
  }
  const license = await Bun.file(join(directory, filename)).text();
  notices.push(`${manifest.name}@${manifest.version}\n\n${license.trim()}`);
}
if (notices.length === 0) {
  throw new Error('No upstream package notices found for the parser bundle');
}
const licenseNotice = `Third-party notices for markdown-parser.generated.js\n\n${notices
  .toSorted()
  .join('\n\n---\n\n')}\n`;

for (const [filename, content] of [
  ['markdown-parser.generated.js', await bundle.text()],
  ['markdown-parser.LICENSE.txt', licenseNotice],
] as const) {
  const output = Bun.file(join(bundleDirectory, filename));
  if (process.argv.includes('--check')) {
    if ((await output.text()) !== content) {
      throw new Error(`${filename} is stale; run bun run adr:parser:build`);
    }
  } else {
    await Bun.write(output, content);
  }
}
